One suggested approach: 

* Try to guess if it is a number
* If yes => use different sorting approach
* Else => sort as strings

{noformat}const colVal = (row: SimulateDynamicScriptResultRow) => {
                    if (input.orderBy?.key === "resultKey") {
                        return resultValue({row});
                    }
                    const keyIdx = data.columns.indexOf(input.orderBy!.key.toString());
                    return row.data[keyIdx].value!;
                };
                const compare = (row1: SimulateDynamicScriptResultRow, row2: SimulateDynamicScriptResultRow) => {
                    const val1 = colVal(row1);
                    const val2 = colVal(row2);

                    // Handle null values
                    if (val1 === null) {
                        return -1;
                    }
                    if (val2 === null) {
                        return 1;
                    }

                    // If both values are numeric, compare as numbers
                    const num1 = Number(val1);
                    const num2 = Number(val2);

                    if (!Number.isNaN(num1) && !Number.isNaN(num2)) {
                        return num1 - num2;
                    }

                    // Otherwise compare as strings
                    const str1 = String(val1);
                    const str2 = String(val2);

                    return str1.localeCompare(str2);
                };
                rows = rows.sort((row1, row2) =>
                    input.orderBy?.direction === "ASC" ? compare(row1, row2) : compare(row2, row1),
                    input.orderBy?.direction === "ASC" ? compare(row1, row2) : compare(row2, row1),{noformat}

